<template><section><div v-if="loadError" class="bio-nexus-message bio-nexus-message-error">{{loadError}}</div><BioNexusDataGrid class="currency-grid" :row-data="rows" :column-defs="columns" :default-col-def="defaults" :components="components" :get-row-id="({data})=>String(data.id)" :quick-filter-text="search" search-enabled v-model:search-model-value="search" search-placeholder="Buscar moneda" refresh-enabled :refreshing="loading" :refresh-disabled="saving" :page-size="10" :page-size-selector="[10,20,50,100]" :min-grid-height="300" :max-grid-height="560" @refresh="load" @row-context-menu="openMenu"><template #actions><button v-if="canCreate" class="bio-nexus-action bio-nexus-action-primary" :disabled="loading||saving" @click="form?.openCreate()"><BioNexusActionIcon action="create"/>Nueva moneda</button></template></BioNexusDataGrid><BioNexusContextMenu ref="menu" :open="context.open" :x="context.x" :y="context.y" :items="menuItems" @close="closeMenu" @select="runMenu"/><CurrencyDialog ref="form" :saving="saving" :can-create="canCreate" :can-update="canUpdate" @submit="save"/><CurrencyStateDialog ref="state" :saving="saving" @confirm="toggle"/></section></template><script setup>import{computed,nextTick,onMounted,ref}from'vue';import BioNexusDataGrid from'@/components/grid/BioNexusDataGrid.vue';import BioNexusGridActionsCell from'@/components/grid/BioNexusGridActionsCell.vue';import BioNexusGridToggleCell from'@/components/grid/BioNexusGridToggleCell.vue';import BioNexusOptionFilter from'@/components/grid/BioNexusOptionFilter.vue';import BioNexusContextMenu from'@/components/ui/BioNexusContextMenu.vue';import BioNexusActionIcon from'@/components/ui/BioNexusActionIcon.vue';import CurrencyDialog from'@/components/currencies/CurrencyDialog.vue';import CurrencyStateDialog from'@/components/currencies/CurrencyStateDialog.vue';import{changeCurrencyStatus,createCurrency,currencyError,getCurrencies,updateCurrency}from'@/services/currencyService';import{useAuthorizationStore}from'@/stores/authorization';import{useBioNexusToast}from'@/composables/useBioNexusToast';const auth=useAuthorizationStore(),toast=useBioNexusToast(),rows=ref([]),search=ref(''),loading=ref(false),saving=ref(false),loadError=ref(''),form=ref(null),state=ref(null),menu=ref(null),context=ref({open:false,x:0,y:0,row:null}),canCreate=computed(()=>auth.hasPermission('currencies.create')),canUpdate=computed(()=>auth.hasPermission('currencies.update')),canStatus=computed(()=>auth.hasPermission('currencies.change-status')),defaults=Object.freeze({sortable:true,filter:true,resizable:true,suppressHeaderMenuButton:true}),components=Object.freeze({BioNexusGridActionsCell,BioNexusGridToggleCell});const columns=computed(()=>[{field:'code',headerName:'Código',width:115},{field:'name',headerName:'Moneda',minWidth:220,flex:1},{field:'symbol',headerName:'Símbolo',width:120},{field:'symbolPosition',headerName:'Posición',width:155,valueFormatter:p=>p.value==='after'?'Después':'Antes'},{field:'decimalPlaces',headerName:'Decimales',width:130,headerClass:'currency-center-header',cellClass:'currency-center-cell'},{colId:'type',headerName:'Tipo',width:140,valueGetter:p=>p.data.isBase?'Base':p.data.isLocal?'Local':'Adicional'},{field:'isActive',headerName:'Estado',width:160,headerClass:'currency-center-header',cellClass:'currency-center-cell',filter:BioNexusOptionFilter,filterParams:{getValue:node=>Boolean(node.data?.isActive),options:[{value:true,label:'Activo'},{value:false,label:'Inactivo'}]},cellRenderer:BioNexusGridToggleCell,cellRendererParams:{onLabel:'Activa',offLabel:'Inactiva',disabled:row=>!canStatus.value||saving.value||Boolean(row?.isBase)||Boolean(row?.isLocal),onToggle:openState}},{colId:'actions',headerName:'Acciones',width:110,pinned:'right',sortable:false,filter:false,resizable:false,cellRenderer:BioNexusGridActionsCell,cellRendererParams:{actions:[{key:'edit',label:'Editar',icon:'edit',visible:()=>canUpdate.value,disabled:()=>saving.value,onClick:openEdit}]}}]),menuItems=computed(()=>{const r=context.value.row;return r?[{key:'edit',label:'Editar',icon:'edit',visible:canUpdate.value,disabled:saving.value,action:()=>openEdit(r)},{key:'state',label:r.isActive?'Inactivar':'Activar',icon:r.isActive?'deactivate':'activate',visible:canStatus.value,disabled:saving.value,action:()=>openState(r)}]:[]});async function load(){if(loading.value||saving.value)return;loading.value=true;loadError.value='';try{rows.value=await getCurrencies()}catch(e){rows.value=[];loadError.value=currencyError(e,'No fue posible consultar las monedas.');toast.error(loadError.value)}finally{loading.value=false}}function replace(v){const a=rows.value.map(x=>x.id===v.id?v:x);if(!a.some(x=>x.id===v.id))a.push(v);rows.value=a.sort((x,y)=>x.name.localeCompare(y.name,'es'))}function openEdit(r){if(canUpdate.value&&!saving.value)form.value?.openEdit(r)}function openState(r){if(canStatus.value&&!saving.value&&!r?.isBase&&!r?.isLocal)state.value?.open(r)}async function openMenu({event,row}){if(!row||(!canUpdate.value&&!canStatus.value))return;event.preventDefault();context.value={open:true,x:event.clientX,y:event.clientY,row};await nextTick();menu.value?.positionMenu?.()}function closeMenu(){context.value={open:false,x:0,y:0,row:null}}async function runMenu(item){const action=item?.action;closeMenu();if(typeof action==='function')await action()}async function save(p){if(saving.value)return;saving.value=true;form.value?.clearError();try{replace(p.mode==='create'?await createCurrency(p.values):await updateCurrency(p.record.id,p.values));form.value?.close();toast.success(p.mode==='create'?'Moneda creada correctamente.':'Moneda actualizada correctamente.')}catch(e){form.value?.setError(currencyError(e,'No fue posible guardar la moneda.'))}finally{saving.value=false}}async function toggle(r){if(saving.value)return;saving.value=true;state.value?.clearError();try{replace(await changeCurrencyStatus(r.id,!r.isActive));state.value?.close();toast.success(r.isActive?'Moneda inactivada correctamente.':'Moneda activada correctamente.')}catch(e){state.value?.setError(currencyError(e,'No fue posible cambiar el estado.'))}finally{saving.value=false}}onMounted(load)</script><style scoped>.currency-grid :deep(.bio-nexus-grid-actions-header .ag-header-cell-label),.currency-grid :deep(.bio-nexus-grid-actions-cell),.currency-grid :deep(.currency-center-header .ag-header-cell-label){justify-content:center}.currency-grid :deep(.currency-center-cell){display:flex;align-items:center;justify-content:center;text-align:center}</style>